using Cnu.AICO.Core.Specs;

namespace Cnu.AICO.Core.Generation;

public enum VerifyStatus
{
    /// <summary>File has a marker and regenerates byte-identically: no model review needed.</summary>
    Verified,
    /// <summary>File has a marker but differs from what the template produces: hand-edited or tampered.</summary>
    Mismatch,
    /// <summary>File was generated by an older template version; regenerate it or remove the marker.</summary>
    Outdated,
    /// <summary>Marker references a template that does not exist or is not crystallized.</summary>
    UnknownTemplate,
    /// <summary>No marker: hand-written (or a suggested integration test), reviewed as usual.</summary>
    NotGenerated,
    /// <summary>File was deleted in the change set.</summary>
    Deleted,
}

public sealed record VerifyResult(string Path, VerifyStatus Status, string? TemplateId, string Detail);

/// <summary>
/// Deterministic replacement for AI review of template output: regenerate from the marker and compare.
/// A change set where every file is <see cref="VerifyStatus.Verified"/> (or deleted) is "template-only".
/// </summary>
public static class RegenVerifier
{
    public static VerifyResult Verify(TemplateRegistry registry, string repoRoot, string relativePath)
    {
        var full = Path.Combine(repoRoot, relativePath);
        if (!File.Exists(full))
            return new(relativePath, VerifyStatus.Deleted, null, "File removed.");

        var content = File.ReadAllText(full).Replace("\r\n", "\n");
        var marker = GeneratedMarker.TryRead(content);
        if (marker is null)
            return new(relativePath, VerifyStatus.NotGenerated, null, "No aico:generated marker.");

        var entry = registry.Find(marker.TemplateId);
        if (entry is null || !entry.IsCrystallized)
            return new(relativePath, VerifyStatus.UnknownTemplate, marker.TemplateId,
                $"Template '{marker.TemplateId}' is missing or not crystallized.");

        if (entry.Spec.Version != marker.Version)
            return new(relativePath, VerifyStatus.Outdated, marker.TemplateId,
                $"Generated with {marker.Version}, template is now {entry.Spec.Version}.");

        var expected = TemplateGenerator.RenderSource(entry.Spec, marker.Source, marker.Parameters);
        if (expected is null)
            return new(relativePath, VerifyStatus.UnknownTemplate, marker.TemplateId, $"Source '{marker.Source}' not in template.");

        if (!string.Equals(expected.Path, relativePath.Replace('\\', '/'), StringComparison.Ordinal))
            return new(relativePath, VerifyStatus.Mismatch, marker.TemplateId, $"Template renders this file at '{expected.Path}'.");

        return string.Equals(expected.Content, content, StringComparison.Ordinal)
            ? new(relativePath, VerifyStatus.Verified, marker.TemplateId, "Regenerates identically.")
            : new(relativePath, VerifyStatus.Mismatch, marker.TemplateId,
                "Content differs from template output. Regenerate it, or remove the marker if the customization is intentional (the file is then reviewed as hand-written).");
    }

    public static bool IsTemplateOnly(IEnumerable<VerifyResult> results) =>
        results.All(r => r.Status is VerifyStatus.Verified or VerifyStatus.Deleted)
        && results.Any(r => r.Status == VerifyStatus.Verified);

    public static bool HasFailures(IEnumerable<VerifyResult> results) =>
        results.Any(r => r.Status is VerifyStatus.Mismatch or VerifyStatus.UnknownTemplate);
}
